import math

def gauss(x,mu,sigma):
    return math.exp(-0.5*((x-mu)/sigma)**2)

years=list(range(1700,2025))
vals=[]
for y in years:
    if y<=1790:
        v=0.0
    elif y<=1850:
        v=(y-1790)/(1850-1790)*0.2
    elif y<=1900:
        v=0.2+(y-1850)/(1900-1850)*0.3
    elif y<=1960:
        v=0.5+(y-1900)/(1960-1900)*0.2
        v += -0.12*gauss(y,1912,4)
        v += -0.08*gauss(y,1963,3)
    elif y<=2000:
        v=0.7+(y-1960)/(2000-1960)*0.5
        v += -0.07*gauss(y,1982,2.5)
        v += -0.10*gauss(y,1991,3)
    else:
        v=1.2+(y-2000)/(2024-2000)*0.55
        v += 0.04*math.sin((y-2000)/2.6)
    vals.append(v)

# simple smoothing (moving average)
sm=[]
for i in range(len(vals)):
    w=0
    s=0
    for j in range(max(0,i-2),min(len(vals),i+3)):
        s+=vals[j]
        w+=1
    sm.append(s/w)

cross=None
for y,v in zip(years,sm):
    if v>=1.5:
        cross=(y,v)
        break
print('cross',cross)
for yr in [1850,1900,2020,2024]:
    i=years.index(yr)
    print(yr,sm[i])
